begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','habitats','canonical habitat catalog');
select has_table('public','species_habitats','canonical links');
select has_table('public','habitat_revisions','immutable habitat revisions');
select is((select count(*)::integer from habitats where kind='group'),8,'eight editorial families');
select is((select count(*)::integer from habitats where kind='type'),45,'subtype coverage');
select is((select count(*)::integer from species where status='active'),1048,'active species preserved');
select is((select count(*)::integer from species where status='active' and kingdom='Plantae'),100,'selected plants preserved');
select is((select count(*)::integer from species where status='archived' and kingdom='Plantae'),3057,'archived plants preserved');
select is((select count(*)::integer from species s where status='active' and not exists(select 1 from species_habitats sh where sh.species_id=s.id)),355,'missing habitat evidence remains missing');
select is((select count(*)::integer from species s where status='active' and ecology->'habitats' is distinct from (select coalesce(jsonb_agg(h.code order by h.code),'[]') from species_habitats sh join habitats h on h.id=sh.habitat_id where sh.species_id=s.id)),0,'canonical links equal ecology projection');
select is((select count(*)::integer from species_habitats sh join habitats h on h.id=sh.habitat_id where (h.kind='type' and scope<>'exact') or (h.kind<>'type' and scope<>'broad')),0,'association precision is explicit');
select is((select count(*)::integer from species_habitats where evidence='[]'),0,'every association retains evidence');
select ok(not exists(select 1 from habitat_aliases where raw_value='Dulce y salobre'),'salinity is not a landscape');
select ok(not has_function_privilege('anon','public.save_habitat(jsonb,integer,text)','execute'),'anonymous cannot edit');
select ok(not has_table_privilege('authenticated','public.habitats','insert'),'browser has no direct writes');
select ok(not has_column_privilege('authenticated','public.habitat_media','evidence_path','select'),'private media evidence excluded');
select throws_ok($$update habitat_revisions set reason='Rewrite' where id=(select id from habitat_revisions limit 1)$$,'P0001','habitat_revision_immutable','revisions cannot be overwritten');
select throws_ok($$insert into habitat_relations(parent_id,child_id) select c.id,p.id from habitats c,habitats p where c.code='rio' and p.code='aguas_continentales'$$,'P0001','habitat_cycle','cycles rejected');
select throws_ok($$insert into habitat_relations select parent_id,child_id from habitat_relations limit 1$$,'23505',null,'duplicate edges rejected');
select throws_ok($$update species set ecology=jsonb_set(ecology,'{habitats}','["inventado"]') where id=(select id from species where status='active' limit 1)$$,'P0001','unknown_habitat:inventado','unknown habitats rejected atomically');
select throws_ok($$update species set ecology=jsonb_set(ecology,'{habitats}','["rio","rio"]') where id=(select id from species where status='active' limit 1)$$,'P0001','duplicate_habitat','duplicate canonical codes rejected');
select ok(exists(select 1 from species_habitats sh join habitats h on h.id=sh.habitat_id where h.kind='aggregate' and not exists(select 1 from habitat_relations r join species_habitats child on child.habitat_id=r.child_id and child.species_id=sh.species_id where r.parent_id=h.id)),'a broad association does not create subtype associations');
select set_config('request.jwt.claims','{"sub":"407fa8fa-b1ab-4473-881d-0404f76045e3","role":"authenticated"}',true);
create temporary table revision_baseline as select count(*) n from species_changes;
select lives_ok($$select normalize_species_habitats(id,updated_at,ecology) from species where status='active'$$,'normalization resumes safely');
select is((select count(*) from species_changes),(select n from revision_baseline),'retry creates no duplicate species revision');
select throws_ok($$select normalize_species_habitats(id,updated_at-interval '1 second',ecology) from species where status='active' limit 1$$,'P0001','species_change_conflict','stale snapshot conflicts');
select throws_ok($$select save_habitat(to_jsonb(h),version+1,'Test conflict') from habitats h limit 1$$,'P0001','habitat_change_conflict','habitat version conflicts');
create temporary table habitat_revision_baseline as select count(*) n from habitat_revisions;
select lives_ok($$select save_habitat(to_jsonb(h),version,'Same approved content') from habitats h$$,'same habitat payload can resume');
select is((select count(*) from habitat_revisions),(select n from habitat_revision_baseline),'identical habitat update creates no revision');
select throws_ok($$select load_habitat_catalog('{"habitats":[],"relations":[],"aliases":[{"raw_value":"Palmares","habitat_code":"rio","rule":"bad"}]}','Test alias')$$,'P0001','habitat_alias_conflict','alias remapping cannot silently change associations');
select throws_ok($$select save_habitat_metric('{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}','Test metric')$$,'P0001','metric_evidence_required','metrics require method denominator source');
select is((select count(*)::integer from habitat_metrics),2,'only documented historical metrics loaded');
select lives_ok($$select save_habitat_metric(to_jsonb(m),'Same historical metric') from habitat_metrics m$$,'metric retry is idempotent');
select is((select count(*) from habitat_revisions),(select n from habitat_revision_baseline),'metric retry adds no revision');
-- Simular una selección editorial posterior. Una reanudación no la sobrescribe
-- usando las formaciones botánicas históricas que siguen conservadas.
create temporary table edited_plant as select id from species where status='active' and kingdom='Plantae' and jsonb_array_length(ecology->'vegetationFormations')>0 limit 1;
update species set ecology=jsonb_set(ecology,'{habitats}','[]') where id=(select id from edited_plant);
select lives_ok($$select normalize_species_habitats(id,updated_at,ecology) from species where id=(select id from edited_plant)$$,'resume respects later canonical editorial selection');
select is((select ecology->'habitats' from species where id=(select id from edited_plant)),'[]'::jsonb,'legacy vegetation cannot recreate deleted canonical associations');
select is((select count(*) from species_changes),(select n from revision_baseline),'resume after canonical edit adds no revision');
select throws_ok($$select save_habitat_media('{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}','Test invalid photo')$$,'P0001','media_evidence_required','photos require checked provenance');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000000","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select save_habitat('{}',null,'Unauthorized')$$,'42501','admin_access_required','noneditor cannot call loader');
reset role;
select * from finish();
rollback;
